// The production WebView uses only custom in-app dialogs. Native browser
// prompts stay disabled so a localhost origin can never leak into the UI.
const prompt = () => null;
const confirm = () => false;
// Keep legacy source strings readable even when a host decodes an older UTF-8 bundle incorrectly.
function repairMojibake(root=document){const map=new Map([[String.fromCharCode(0xc2,0xb7),'·'],[String.fromCharCode(0xe2,0x80,0x99),'’'],[String.fromCharCode(0xe2,0x80,0xa6),'…'],[String.fromCharCode(0xe2,0x86,0x92),'→']]);const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const node of nodes){let value=node.nodeValue;for(const [bad,good] of map)value=value.split(bad).join(good);if(value!==node.nodeValue)node.nodeValue=value}}
document.addEventListener('DOMContentLoaded',()=>{const root=document.querySelector('.app-shell');if(!root)return;const observer=new MutationObserver(()=>repairMojibake(root));observer.observe(root,{subtree:true,childList:true,characterData:true});repairMojibake(root)});
document.addEventListener('DOMContentLoaded',()=>{const oldAudioRender=render;render=()=>{oldAudioRender();if(page==='settings'&&!document.querySelector('#audioTools')){const row=document.createElement('div');row.className='setting-row';row.id='audioTools';row.innerHTML='<div><strong>Mute SCP:SL while waiting</strong><small>Mute only the game audio during an active auto-join run, then restore its previous state.</small></div><label class="toggle"><input type="checkbox" data-setting="mute_game_audio" '+(state.settings.mute_game_audio?'checked':'')+'><span>Mute game audio</span></label>';document.querySelector('.settings .panel')?.appendChild(row);row.querySelector('input').onchange=async e=>{const r=await call('save_setting','mute_game_audio',e.target.checked);if(r?.settings)state.settings=r.settings;toast(e.target.checked?'Game audio will mute during runs':'Game audio muting disabled')}}}});
const $=(s,root=document)=>root.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), api=()=>window.pywebview?.api;
let pendingConfirm=null;function ask(message,options={}){const modal=$('#confirmModal');if(!modal)return Promise.resolve(false);$('#confirmTitle').textContent=options.title||'Confirm action';$('#confirmMessage').textContent=message;$('#confirmAccept').textContent=options.confirmText||'Continue';$('#confirmAccept').classList.toggle('danger',!!options.danger);modal.hidden=false;$('#confirmAccept').focus();return new Promise(resolve=>{pendingConfirm=resolve})}function finishConfirm(result){if(!pendingConfirm)return;const resolve=pendingConfirm;pendingConfirm=null;$('#confirmModal').hidden=true;resolve(result)}document.addEventListener('click',e=>{if(e.target.id==='confirmAccept')finishConfirm(true);if(e.target.id==='confirmCancel'||e.target.id==='confirmModal')finishConfirm(false)});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#confirmModal')?.hidden){e.preventDefault();finishConfirm(false)}});
let state={servers:[],groups:[],settings:{retry_interval_s:2,max_attempts:100,max_minutes:30,connection_method:'automatic'},calibration:{calibrated:false,points:{}},packs:{packs:[],active_pack:null},theme:{preset:'violet'},storage:{migrated:false,paths:{}}},page='join',selected=null,events=[],runState={label:'READY',message:'Waiting for a run.',attempt:null};
async function call(n,...a){try{return api()?.[n]?await api()[n](...a):null}catch(e){toast(e.message||'Request failed');return null}} function toast(s){const x=$('#toast');x.textContent=s;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),3000)} function addLog(s){events.unshift('['+new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})+'] '+s);if(page==='join'&&window.refreshJoinRun?.())return;render()}
function head(t,d){return '<div class="page-head"><div><div class="eyebrow">CONTAINMENT OPERATIONS / '+page.toUpperCase()+'</div><h1>'+t+'</h1><p>'+d+'</p></div></div>'}
function join(){const s=state.servers.find(x=>x.id===selected)||state.servers[0];return '<section class="page">'+head('Auto-Join','Keeps trying until SCP:SL accepts the connection. Every decision is shown in the live activity feed.')+'<div class="layout"><div><section class="panel selected"><div class="label">SELECTED DESTINATION</div><div class="server-name">'+(s?esc(s.name):'No saved server')+'</div><div class="endpoint">'+(s?esc(s.ip)+':'+s.port:'Add one from Servers')+'</div><div class="actions"><button class="button primary" id="start" '+(s?'':'disabled')+'>Start auto-join</button><button class="button" id="stop">Stop</button><button class="button" data-go="servers">Choose server</button></div></section><section class="panel" style="margin-top:18px"><div class="feed-head"><span>RUN STATUS</span><strong class="status">READY</strong></div><div class="timeline">'+['SELECT','LAUNCH','CONNECT','FULL','RETRY','JOINED'].map((x,i)=>'<div class="step '+(i<1?'done':'')+'"><i></i>'+x+'</div>').join('')+'</div><p class="endpoint">Retry delay: '+(state.settings.retry_interval_s||2)+' seconds. 0 means unlimited where configured.</p><div class="feed"><div class="feed-head"><span>LIVE ACTIVITY</span><span>'+events.length+' EVENTS</span></div><div class="log">'+(events.map(esc).join('<br>')||'Waiting for a run.')+'</div></div></section></div><aside class="panel"><div class="label">LOCAL CHECK</div><h2>'+(state.calibration.calibrated?'Calibration ready':'Automatic input enabled')+'</h2><p>Targets use the live SCP:SL client rectangle. Calibration is an optional precision fallback.</p><button class="button" data-go="diagnostics">Open diagnostics</button></aside></div></section>'}
function servers(){const q=window.serverQuery||'';const list=state.servers.filter(s=>!q||(s.name+' '+s.ip+' '+s.port).toLowerCase().includes(q.toLowerCase()));return '<section class="page">'+head('Servers','Keep saved destinations, inspect live status, and build ordered retry groups.')+'<div class="layout"><section class="panel"><div class="field"><label for="search">SEARCH SAVED SERVERS</label><input class="input" id="search" placeholder="Name or endpoint" value="'+esc(q)+'"></div><div class="server-list">'+(list.map(s=>'<div class="server-row '+(s.id===selected?'selected-row':'')+'" data-server="'+esc(s.id)+'"><main><strong>'+esc(s.name)+'</strong><small>'+esc(s.ip)+':'+s.port+'</small></main><span class="meta">'+(s.status?.players??'--')+'/'+(s.status?.max_players??'--')+' · '+(s.status?.latency_ms??'--')+' ms</span><button class="button" data-refresh="'+esc(s.id)+'">Refresh</button><button class="button danger" data-delete="'+esc(s.id)+'">Delete</button></div>').join('')||'<div class="empty">No saved servers match that search.</div>')+'</div><div class="actions"><button class="button primary" id="addServer">Add server</button></div></section><section class="panel"><div class="label">ORDERED GROUPS</div><h2>Retry groups</h2><p>Try servers in order and loop until one accepts.</p><div class="table-list">'+(state.groups.map(g=>'<div class="table-item"><span>'+esc(g.name)+' <small>'+g.server_ids.length+' servers</small></span><button class="button danger" data-group-delete="'+esc(g.id)+'">Delete</button></div>').join('')||'<div class="empty">No groups yet.</div>')+'</div><button class="button" id="addGroup">Create group</button></section></div></section>'}
function diagnostics(){return '<section class="page">'+head('Diagnostics','Inspect the game window and calibrate without clicking inside SCP:SL.')+'<div class="layout"><section class="panel"><div class="label">CALIBRATION WIZARD</div><h2>'+(state.calibration.calibrated?'Calibration saved':'Optional precision setup')+'</h2><p>Move the pointer over the named control, then press Capture. The app never asks you to click the game.</p><div class="field"><label>CONTROL TO CAPTURE</label><select id="calName">'+['servers_tab','direct_connect','ip_field','connect_button'].map(x=>'<option>'+x+'</option>').join('')+'</select></div><button class="button primary" id="capture">Capture pointer position</button> <button class="button" id="saveCal">Save calibration</button><pre class="log" id="calPreview">'+esc(JSON.stringify(state.calibration.points||{},null,2))+'</pre></section><aside class="panel"><div class="label">LIVE INPUT CHECK</div><h2>Display facts</h2><p>Calculated targets follow the client rectangle and saved physical-pixel metadata.</p><button class="button" id="runDiag">Run input diagnostic</button><pre id="diagOutput" class="empty">No diagnostic run yet.</pre></aside></div></section>'}
function packs(){return '<section class="page">'+head('Text Packs','Install local translation folders or ZIP files and switch between a custom pack and SCP:SL default.')+'<div class="layout"><section class="panel"><div class="label">IMPORT</div><h2>Bring in a pack</h2><p>Nothing is executed. Only pack files are copied.</p><div class="dropzone" id="dropzone"><strong>Drop a folder or ZIP here</strong><span>or use a native picker below</span><input id="packFile" type="file" accept=".zip" hidden><div class="actions"><button class="button" id="pickPack">Choose ZIP</button><button class="button" id="pickFolder">Choose folder</button></div></div><div class="field"><label for="packSearch">DISCOVER ON GITHUB</label><input class="input" id="packSearch" placeholder="SCP:SL translation"><button class="button" id="searchPacks">Search repositories</button></div></section><section class="panel"><div class="label">INSTALLED</div><h2>Your packs</h2><div class="table-list">'+(state.packs.packs?.map(p=>'<div class="table-item"><span><strong>'+esc(p.name)+'</strong><small>'+esc((p.authors||[]).join(', '))+'</small></span><button class="button" data-activate="'+esc(p.id)+'">Activate</button><button class="button danger" data-pack-delete="'+esc(p.id)+'">Delete</button></div>').join('')||'<div class="empty">No custom packs installed.</div>')+'</div><button class="button" id="defaultPack">Use SCP:SL default</button><div id="packResults"></div></section></div></section>'}
function settings(){const x=state.settings,storageNotice=state.storage?.migrated?'<div class="storage-notice" role="status"><strong>Imported from existing local data</strong><small>Saved servers and calibration from earlier versions are available in this build.</small></div>':'';return '<section class="page settings">'+head('Settings','Tune retry behavior, input compatibility, notifications, appearance, and local storage.')+'<section class="panel">'+storageNotice+[['connection_method','Connection method','Automatic, Foreground, or Background-only.'],['retry_interval_s','Retry delay','Seconds between rejected/full attempts.'],['max_attempts','Maximum attempts','Use 0 for unlimited attempts.'],['max_minutes','Maximum runtime','Minutes; use 0 for unlimited runtime.']].map(a=>'<div class="setting-row"><div><strong>'+a[1]+'</strong><small>'+a[2]+'</small></div><input class="input" data-setting="'+a[0]+'" value="'+esc(x[a[0]]??'')+'"></div>').join('')+'<div class="setting-row"><div><strong>Theme preset</strong><small>Choose a restrained built-in accent.</small></div><div class="swatches">'+[['violet','#b186ff'],['amber','#e0a458'],['slate','#71b7d8']].map(a=>'<button class="swatch" title="'+a[0]+'" style="background:'+a[1]+'" data-theme="'+a[0]+'"></button>').join('')+'</div></div><div class="actions"><button class="button primary" id="saveSettings">Save settings</button><button class="button" id="bugReport">Create bug report</button></div></section></section>'}
function help(){return '<section class="page">'+head('Help','Plain-language guidance for waiting, recovering, and configuring the tool.')+'<div class="grid-2"><section class="panel"><div class="label">FIRST RUN</div><h2>Choose, configure, start</h2><p>Select a saved server, set 0 for unlimited limits if desired, then start. Calibration is optional.</p></section><section class="panel"><div class="label">RETRY STATES</div><h2>Every decision is visible</h2><p>Full, rejected, disconnected, timeout, and unclear are separate states. Direct Connect is reused when available.</p></section><section class="panel"><div class="label">LOCAL STORAGE</div><h2>Your data stays here</h2><p>Servers, groups, settings, calibration, themes, and reports are stored in AppData.</p></section><section class="panel"><div class="label">TROUBLESHOOTING</div><h2>Diagnostics first</h2><p>Run the input check and attach the generated report with your resolution and DPI scale.</p></section></div></section>'}
function render(){const f={join,servers,packs,diagnostics,settings,help}[page];$('#content').innerHTML=f();$('#crumb').textContent=page.toUpperCase();document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===page));wire()}
function wire(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{page=b.dataset.go;render()});$('#start')?.addEventListener('click',async()=>{const s=state.servers.find(x=>x.id===selected)||state.servers[0];if((await call('start_join',s.id))?.ok)addLog('Auto-join started.')});$('#stop')?.addEventListener('click',async()=>{await call('stop_join');addLog('Stop requested.')});$('#search')?.addEventListener('input',e=>{window.serverQuery=e.target.value;render()});document.querySelectorAll('[data-server]').forEach(b=>b.onclick=()=>{selected=b.dataset.server;page='join';render()});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=async e=>{e.stopPropagation();if(confirm('Delete this saved server?')){await call('delete_server',b.dataset.delete);state.servers=state.servers.filter(x=>x.id!==b.dataset.delete);render()}});document.querySelectorAll('[data-refresh]').forEach(b=>b.onclick=async e=>{e.stopPropagation();const r=await call('refresh_server_status',b.dataset.refresh);const s=state.servers.find(x=>x.id===b.dataset.refresh);if(s&&r?.status){s.status=r.status;const meta=b.closest('.server-row')?.querySelector('.meta');if(meta)meta.textContent=(r.status.players??'--')+'/'+(r.status.max_players??'--')+' · '+(r.status.latency_ms??'--')+' ms'}});$('#addServer')?.addEventListener('click',async()=>{const n=prompt('Server name'),e=prompt('IP or hostname:port'),parts=String(e||'').split(':');if(n&&parts.length===2){const r=await call('save_server',n,parts[0],Number(parts[1]));if(r?.server)state.servers.push(r.server);render()}});document.querySelectorAll('[data-setting]').forEach(e=>e.onchange=async()=>{const numeric=['retry_interval_s','max_attempts','max_minutes'].includes(e.dataset.setting);const r=await call('save_setting',e.dataset.setting,numeric?Number(e.value):e.value);if(r?.settings)state.settings=r.settings});$('#saveSettings')?.addEventListener('click',()=>toast('Settings saved'));document.querySelectorAll('[data-theme]').forEach(b=>b.onclick=async()=>{const r=await call('set_theme',b.dataset.theme);if(r?.theme){state.theme=r.theme;document.documentElement.style.setProperty('--accent',{violet:'#b186ff',amber:'#e0a458',slate:'#71b7d8'}[b.dataset.theme]);render()}});$('#bugReport')?.addEventListener('click',async()=>{if((await call('create_bug_report'))?.ok)toast('Bug report created in AppData')});$('#capture')?.addEventListener('click',async()=>{const n=$('#calName').value,r=await call('capture_calibration_point',n);if(r?.point){state.calibration.points[n]=r.point;$('#calPreview').textContent=JSON.stringify(state.calibration.points,null,2);toast('Position captured')}});$('#saveCal')?.addEventListener('click',async()=>{const r=await call('save_calibration',state.calibration.points);if(r?.calibration)state.calibration=r.calibration;toast('Calibration saved')});$('#runDiag')?.addEventListener('click',async()=>{$('#diagOutput').textContent=JSON.stringify(await call('run_input_diagnostic'),null,2)});$('#pickPack')?.addEventListener('click',async()=>{const result=await call('pick_translation_source','file');if(result?.path)importPath(result.path);else if(result?.error)toast(result.error)});$('#pickFolder')?.addEventListener('click',async()=>{const result=await call('pick_translation_source','folder');if(result?.path)importPath(result.path);else if(result?.error)toast(result.error)});$('#packFile')?.addEventListener('change',e=>importFile(e.target.files[0]));$('#dropzone')?.addEventListener('dragover',e=>{e.preventDefault();e.dataTransfer.dropEffect='copy'});$('#dropzone')?.addEventListener('drop',e=>{e.preventDefault();importFile(e.dataTransfer.files[0])});$('#defaultPack')?.addEventListener('click',async()=>{const r=await call('deactivate_translation_pack');if(r?.packs)state.packs=r.packs;render()});document.querySelectorAll('[data-activate]').forEach(b=>b.onclick=async()=>{const r=await call('activate_translation_pack',b.dataset.activate);if(r?.packs)state.packs=r.packs;render()});document.querySelectorAll('[data-pack-delete]').forEach(b=>b.onclick=async()=>{if(confirm('Delete this pack?')){const r=await call('delete_translation_pack',b.dataset.packDelete);if(r?.packs)state.packs=r.packs;render()}})}
async function importPath(path){if(!path)return;const r=await call('import_translation_pack',path,'');if(r?.ok){state.packs=r.packs;render()}else toast(r?.error||'Could not import pack')}
async function importFile(f){if(!f)return;if(f.path)return importPath(f.path);toast('Use Choose ZIP or Choose folder so WebView2 can provide the local path.')}
window.__appEvent=e=>{const data=e?.data||{},message=data.message||data.result||'';if(e?.event==='watching')runState={label:'WATCHING',message:message||'Watching server capacity before opening the game.',attempt:null};else if(e?.event==='slot_candidate')runState={label:'SLOT CANDIDATE',message:message||'Confirming an available slot.',attempt:null};else if(e?.event==='join_attempt_started')runState={label:'CONNECTING',message:message||'Connecting to saved destination.',attempt:data.attempt??null};else if(e?.event==='join_retrying')runState={label:'RETRYING',message:message||'Retrying the selected destination.',attempt:data.attempt??null};else if(e?.event==='join_succeeded'){runState={label:'JOINED',message:message||'Connected to server.',attempt:data.attempt??null};toast('Joined successfully')}else if(e?.event==='join_failed'){runState={label:'FAILED',message:message||'Run ended: '+(data.result||'unknown'),attempt:data.attempt??null};toast(runState.message)}else if(e?.event==='status_changed'&&message){const lower=message.toLowerCase();runState={label:lower.includes('watch')?'WATCHING':lower.includes('slot')?'SLOT CANDIDATE':lower.includes('retry')?'RETRYING':lower.includes('connect')?'CONNECTING':runState.label,message,attempt:runState.attempt}}if(message)addLog(message);else if(page==='join')render();if(page==='join'){const indicator=document.querySelector('.status');if(indicator){indicator.classList.add('run-state');indicator.textContent=runState.label}}};document.querySelectorAll('.nav-item').forEach(b=>b.onclick=()=>{page=b.dataset.page;render()});$('#collapse').onclick=()=>$('#sidebar').classList.toggle('collapsed');$('#mobileMenu').onclick=()=>$('#sidebar').classList.toggle('open');
function bootError(message){const content=$('#content');if(!content)return;content.innerHTML='<section class="boot-state error" role="alert"><div class="boot-mark">!</div><h1>Could not connect to the app</h1><p>'+esc(message)+'</p><button class="button primary" id="retryBoot">Try again</button></section>';$('#retryBoot')?.addEventListener('click',boot)}
function waitForBridge(timeout=10000){if(api()&&Object.keys(api()).length)return Promise.resolve(api());return new Promise((resolve,reject)=>{const started=Date.now();let timer;const finish=()=>{const bridge=api();if(bridge&&Object.keys(bridge).length){clearInterval(timer);window.removeEventListener('pywebviewready',finish);resolve(bridge);return}if(Date.now()-started>=timeout){clearInterval(timer);window.removeEventListener('pywebviewready',finish);reject(new Error('The local WebView bridge did not start. Close any other SCP:SL Auto-Joiner window and try again.'))}};window.addEventListener('pywebviewready',finish);timer=setInterval(finish,100);finish()})}
async function boot(){try{await waitForBridge();const r=await call('get_app_state');if(!r?.ok)throw new Error(r?.error||'The application state could not be loaded.');state=r;selected=state.servers[0]?.id||null;$('#gameStatus').textContent='GAME DETECTED';render()}catch(e){bootError(e?.message||'Startup failed.')}}boot();
document.addEventListener('click',async e=>{const b=e.target.closest('[data-rename],[data-group-delete]');if(!b)return;e.stopPropagation();if(b.dataset.rename){const s=state.servers.find(x=>x.id===b.dataset.rename),name=prompt('New server name',s?.name||'');if(name&&s){const r=await call('rename_server',s.id,name);if(r?.server)s.name=r.server.name;render()}}else if(b.dataset.groupDelete){if(confirm('Delete this group?')){const r=await call('delete_group',b.dataset.groupDelete);if(r?.deleted){state.groups=state.groups.filter(x=>x.id!==b.dataset.groupDelete);render()}}}});
const renderPage=render;render=()=>{renderPage();document.querySelectorAll('[data-server]').forEach(row=>{if(!row.querySelector('[data-rename]')){const b=document.createElement('button');b.className='button';b.dataset.rename=row.dataset.server;b.textContent='Rename';row.appendChild(b)}})};
document.addEventListener('click',async e=>{if(e.target.id==='addGroup'){const name=prompt('Group name');if(name){const r=await call('save_group',name,state.servers.map(s=>s.id));if(r?.group)state.groups.push(r.group);render()}}});
const renderWithTheme=render;render=()=>{renderWithTheme();if(page==='settings'){const panel=document.querySelector('.settings .panel');if(panel&&!document.querySelector('#customThemeCss')){const box=document.createElement('div');box.className='setting-row';box.innerHTML='<div><strong>Custom CSS theme</strong><small>Styling only. Imports, URLs, scripts, and event handlers are rejected.</small></div><div><textarea class="input" id="customThemeCss" rows="4" placeholder=".panel { border-color: #b186ff; }"></textarea><button class="button" id="saveThemeCss">Import CSS</button></div>';panel.appendChild(box);document.querySelector('#saveThemeCss').onclick=async()=>{const r=await call('save_custom_theme','custom.css',document.querySelector('#customThemeCss').value);if(r?.ok)toast('Custom theme saved');else toast(r?.error||'Theme rejected')}}}};

function documentation(){return '<section class="page documentation">'+head('Documentation','A quick reference for configuring and using SCP:SL Auto-Joiner.')+'<div class="grid-2"><section class="panel"><div class="label">GETTING STARTED</div><h2>1. Select a destination</h2><p>Open Servers, add or select a saved endpoint, then return to Auto-Join and press Start auto-join.</p></section><section class="panel"><div class="label">RETRY BEHAVIOR</div><h2>2. Let it work</h2><p>The app reuses Direct Connect after a full or rejected attempt. Set retry delay, attempts, and runtime in Settings. A value of 0 means unlimited.</p></section><section class="panel"><div class="label">CALIBRATION</div><h2>When to calibrate</h2><p>Automatic controls use the live game window. Use Diagnostics only if a control is missed after a display, DPI, or game layout change.</p></section><section class="panel"><div class="label">TROUBLESHOOTING</div><h2>Read the evidence</h2><p>Check Live Activity for full, rejected, timeout, disconnected, or unclear results. Create a bug report from Settings and include your display scale.</p></section><section class="panel"><div class="label">DATA & PRIVACY</div><h2>Local by default</h2><p>Servers, groups, calibration, themes, and reports stay in your local AppData folder. Imported translation packs are copied as files and never executed.</p></section><section class="panel"><div class="label">SUPPORT</div><h2>Report an issue</h2><p>Include the generated report, SCP:SL version, window mode, resolution, DPI scale, and the relevant activity log lines.</p></section></div></section>'}
const oldRenderForDocs=render;render=()=>{oldRenderForDocs();if(page==='docs')document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===page));};
const docsNav=document.createElement('button');docsNav.className='nav-item';docsNav.dataset.page='docs';docsNav.innerHTML='<span>07</span>Documentation';document.querySelector('nav').appendChild(docsNav);docsNav.onclick=()=>{page='docs';render()};
const oldPageRender=render;render=()=>{if(page==='docs'){document.querySelector('#content').innerHTML=documentation();document.querySelector('#crumb').textContent='DOCUMENTATION';document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===page));return}oldPageRender()};
const oldAppearanceRender=render;render=()=>{oldAppearanceRender();if(page==='settings'){const panel=document.querySelector('.settings .panel');if(panel&&!document.querySelector('#appearanceTools')){const box=document.createElement('div');box.className='setting-row';box.id='appearanceTools';box.innerHTML='<div><strong>Appearance controls</strong><small>Choose an accent color or save sanitized CSS styling for this app.</small></div><div class="appearance-tools"><div class="color-picker"><label for="accentColor">Accent color</label><input id="accentColor" type="color" value="#b186ff"></div><textarea class="input theme-editor" id="themeEditor" placeholder=".panel { border-color: #b186ff; }"></textarea><button class="button" id="saveThemeStyle">Save custom appearance</button></div>';panel.appendChild(box);$('#accentColor').value=state.settings.custom_accent||'#b186ff';$('#accentColor').oninput=async e=>{document.documentElement.style.setProperty('--accent',e.target.value);await call('save_setting','accent','custom');const r=await call('save_setting','custom_accent',e.target.value);if(r?.settings)state.settings={...state.settings,...r.settings}};$('#saveThemeStyle').onclick=async()=>{const css=$('#themeEditor').value.trim();const r=await call('save_custom_theme','custom.css',css);toast(r?.ok?'Custom appearance saved':(r?.error||'Theme rejected'))}}}};

documentation=()=>`<section class="page documentation">${head('Documentation','How the app works, including themes, appearance controls, and troubleshooting.')}<section class="panel"><div class="label">APPEARANCE</div><h2>Customize the look</h2><p>Open Settings and use Theme preset for a quick accent change. Violet is the default; Amber and Slate change the accent while keeping the same readable containment layout.</p><div class="table-list"><div class="table-item"><span><strong>Accent color</strong><small>Pick any color with the native color selector. It changes buttons, borders, labels, focus rings, and the scrollbar accent immediately.</small></span></div><div class="table-item"><span><strong>Custom CSS</strong><small>Enter selectors such as <code>.panel { border-color: #b186ff; }</code>, then choose Save custom appearance. Styling is stored locally.</small></span></div><div class="table-item"><span><strong>Safe styling rules</strong><small>Only styling data is accepted. External imports, URLs, scripts, expressions, and event-handler rules are rejected; imported CSS is never executed as application code.</small></span></div></div></section><div class="grid-2"><section class="panel"><div class="label">AUTO-JOIN</div><h2>What each state means</h2><p>Select a server or group, choose timing in Settings, and start. The activity feed reports launch, Direct Connect, full/rejected, retry, disconnect, timeout, unclear, and joined states.</p></section><section class="panel"><div class="label">SERVERS</div><h2>Saved destinations</h2><p>Add an IP or hostname with its port, rename entries, refresh their status, or delete them. Groups try saved servers in their stored order.</p></section><section class="panel"><div class="label">DIAGNOSTICS</div><h2>Calibration and testing</h2><p>Automatic mode uses the live SCP:SL client rectangle. Calibrate only when navigation misses a control after changing resolution, DPI, or window layout. The preview shows saved targets.</p></section><section class="panel"><div class="label">TEXT PACKS</div><h2>Translations</h2><p>Drop in a supported folder or ZIP. The manager copies translation files, tracks backups, and lets you activate one custom pack or return to SCP:SL’s default.</p></section><section class="panel"><div class="label">SETTINGS</div><h2>Timing and input</h2><p>Retry delay controls the wait between attempts. Maximum attempts and runtime stop the run; entering 0 makes either limit unlimited. Choose Automatic, Foreground, or Background-only based on client compatibility.</p></section><section class="panel"><div class="label">HELP & REPORTS</div><h2>When something fails</h2><p>Read the live log first, then create a bug report from Settings. Include SCP:SL version, display resolution, DPI scale, window mode, and the exact status message.</p></section></div></section>`;
const oldAppearancePolish=render;render=()=>{oldAppearancePolish();if(page==='settings'){document.querySelector('#customThemeCss')?.closest('.setting-row')?.remove();const toolsBox=document.querySelector('#appearanceTools .appearance-tools');if(toolsBox&&!document.querySelector('#resetAppearance')){const reset=document.createElement('button');reset.id='resetAppearance';reset.className='button';reset.textContent='Reset to default';toolsBox.appendChild(reset);reset.onclick=async()=>{if(!await ask('Reset theme colors and custom CSS to the default violet appearance?',{title:'Reset appearance',confirmText:'Reset'}))return;const r=await call('set_theme','violet');document.documentElement.classList.remove('light-mode','light-warm','light-slate');document.documentElement.style.setProperty('--accent','#b186ff');if(r?.theme)state.theme=r.theme;$('#accentColor').value='#b186ff';$('#themeEditor').value='';toast('Appearance reset to default')}}}};
// The primary Join page must be able to start either a saved server or an
// ordered group. Groups are no longer hidden behind the Servers editor.
let selectedTarget={type:'server',id:null};
const joinPageWithTargets=join;
join=()=>{const type=selectedTarget.type,options=type==='group'?state.groups:state.servers,id=selectedTarget.id||options[0]?.id||'',target=options.find(item=>item.id===id),details=type==='group'?(target?target.server_ids.length+' saved servers in retry order':'No saved group'):(target?target.ip+':'+target.port:'No saved server');return '<section class="page">'+head('Auto-Join','Choose one saved server or a retry group, then let the app keep trying until SCP:SL accepts the connection.')+'<div class="layout"><div><section class="panel selected"><div class="label">SELECTED DESTINATION</div><div class="field"><label for="targetType">DESTINATION TYPE</label><select class="input" id="targetType"><option value="server" '+(type==='server'?'selected':'')+'>Saved server</option><option value="group" '+(type==='group'?'selected':'')+'>Ordered server group</option></select></div><div class="field"><label for="targetSelect">DESTINATION</label><select class="input" id="targetSelect">'+options.map(item=>'<option value="'+esc(item.id)+'" '+(item.id===id?'selected':'')+'>'+esc(item.name)+'</option>').join('')+'</select></div><div class="server-name">'+esc(target?.name||'No saved destination')+'</div><div class="endpoint">'+esc(details)+'</div><div class="actions"><button class="button primary" id="start" '+(target?'':'disabled')+'>Start auto-join</button><button class="button" id="stop">Stop</button><button class="button" data-go="servers">Manage destinations</button></div></section><section class="panel" style="margin-top:18px"><div class="feed-head"><span>RUN STATUS</span><strong class="status">READY</strong></div><div class="timeline">'+['SELECT','LAUNCH','CONNECT','FULL','RETRY','JOINED'].map((x,i)=>'<div class="step '+(i<1?'done':'')+'"><i></i>'+x+'</div>').join('')+'</div><p class="endpoint">Retry delay: '+(state.settings.retry_interval_s||2)+' seconds. 0 means unlimited where configured.</p><div class="feed"><div class="feed-head"><span>LIVE ACTIVITY</span><span>'+events.length+' EVENTS</span></div><div class="log">'+(events.map(esc).join('<br>')||'Waiting for a run.')+'</div></div></section></div><aside class="panel"><div class="label">LOCAL CHECK</div><h2>'+(state.calibration.calibrated?'Calibration ready':'Automatic input enabled')+'</h2><p>Targets use the live SCP:SL client rectangle. Calibration is an optional precision fallback.</p><button class="button" data-go="diagnostics">Open diagnostics</button></aside></div></section>'};
const wireWithTargets=wire;wire=()=>{wireWithTargets();if(page!=='join')return;$('#targetType').onchange=event=>{selectedTarget={type:event.target.value,id:null};render()};$('#targetSelect').onchange=event=>{selectedTarget={type:selectedTarget.type,id:event.target.value}};const oldStart=$('#start');if(oldStart){const start=oldStart.cloneNode(true);oldStart.replaceWith(start);start.onclick=async()=>{const type=selectedTarget.type,options=type==='group'?state.groups:state.servers,id=selectedTarget.id||options[0]?.id;if(!id)return;const result=await call('start_join',id,type);if(result?.ok)addLog('Auto-join started for '+(type==='group'?'group.':'server.'))}}};

// Calibration is a short guided sequence.  It never requires clicking inside
// the game: position the pointer over the named control, then capture here.
const calibrationControls=['servers_tab','direct_connect','ip_field','connect_button'];let calibrationStep=0;
diagnostics=()=>{const control=calibrationControls[calibrationStep],complete=calibrationStep>=calibrationControls.length;return '<section class="page">'+head('Diagnostics','Inspect the game window and calibrate without clicking inside SCP:SL.')+'<div class="layout"><section class="panel"><div class="label">CALIBRATION WIZARD</div><h2>'+(state.calibration.calibrated?'Calibration saved':'Optional precision setup')+'</h2><p>Step '+Math.min(calibrationStep+1,calibrationControls.length)+' of '+calibrationControls.length+'. Move the pointer over this SCP:SL control, then capture it here.</p><div class="field"><label>NEXT CONTROL</label><strong id="calibrationControl">'+esc(control||'All controls captured')+'</strong></div><div class="actions"><button class="button primary" id="captureCalibration" '+(complete?'disabled':'')+'>Capture pointer position</button><button class="button" id="resetCalibration">Reset</button><button class="button" id="saveCalibration" '+(complete?'':'disabled')+'>Save calibration</button></div><pre class="log" id="calPreview">'+esc(JSON.stringify(state.calibration.points||{},null,2))+'</pre></section><aside class="panel"><div class="label">LIVE INPUT CHECK</div><h2>Display facts</h2><p>Calculated targets follow the client rectangle and saved physical-pixel metadata.</p><button class="button" id="runDiag">Run input diagnostic</button><pre id="diagOutput" class="empty">No diagnostic run yet.</pre></aside></div></section>'};
const wireWithCalibration=wire;wire=()=>{wireWithCalibration();if(page!=='diagnostics')return;$('#captureCalibration')?.addEventListener('click',async()=>{const name=calibrationControls[calibrationStep],result=await call('capture_calibration_point',name);if(!result?.point)return toast('Could not capture the pointer position');state.calibration.points[name]=result.point;calibrationStep+=1;render();toast('Captured '+name)});$('#resetCalibration')?.addEventListener('click',()=>{calibrationStep=0;state.calibration.points={};render()});$('#saveCalibration')?.addEventListener('click',async()=>{const result=await call('save_calibration',state.calibration.points,state.calibration.metadata||{});if(result?.calibration){state.calibration=result.calibration;toast('Calibration saved');render()}});$('#runDiag')?.addEventListener('click',async()=>{$('#diagOutput').textContent=JSON.stringify(await call('run_input_diagnostic'),null,2)})};

// The first-run guidance is local and passive: it reports readiness without
// launching SCP:SL or starting a connection.
help=()=>{const serverReady=state.servers.length>0,calibrationReady=!!state.calibration.calibrated,storageReady=!!state.storage?.paths?.root;return '<section class="page">'+head('Help','Plain-language guidance for waiting, recovering, and configuring the tool.')+'<section class="panel" id="onboardingReadiness"><div class="label">FIRST-RUN READINESS</div><h2>Before you start</h2><div class="table-list"><div class="table-item"><span><strong>'+ (serverReady?'Saved server ready':'Add a saved server')+'</strong><small>'+ (serverReady?'Select it from Auto-Join or Servers.':'Open Servers and add an IP or remember a connection.')+'</small></span></div><div class="table-item"><span><strong>'+ (calibrationReady?'Calibration ready':'Calibration optional')+'</strong><small>'+ (calibrationReady?'Saved client-relative targets are available.':'Use Diagnostics only if automatic navigation misses a control.')+'</small></span></div><div class="table-item"><span><strong>'+ (storageReady?'Local storage ready':'Local storage unavailable')+'</strong><small>Servers, groups, settings, packs, and reports stay on this PC.</small></span></div></div></section><div class="grid-2"><section class="panel"><div class="label">RETRY STATES</div><h2>Every decision is visible</h2><p>Full, rejected, disconnected, timeout, and unclear are separate states. Direct Connect is reused when available.</p></section><section class="panel"><div class="label">TROUBLESHOOTING</div><h2>Diagnostics first</h2><p>Run the input check and attach the generated report with your resolution and DPI scale.</p></section></div></section>'};

packs=()=>'<section class="page">'+head('Text Packs','Install local translation folders or ZIP files and switch between a custom pack and SCP:SL default.')+'<div class="layout"><section class="panel"><div class="label">IMPORT</div><h2>Bring in a pack</h2><p>Nothing is executed. Only translation pack files are copied.</p><div class="dropzone" id="dropzone"><strong>Drop a folder or ZIP here</strong><span>or use a native picker below</span><input id="packFile" type="file" accept=".zip" hidden><div class="actions"><button class="button" id="pickPack">Choose ZIP</button><button class="button" id="pickFolder">Choose folder</button></div></div><div class="field"><label for="directPackLink">INSTALL FROM LINK</label><div class="actions"><input class="input" id="directPackLink" placeholder="GitHub repository, release, or direct ZIP URL"><button class="button" id="installDirectPackLink">Install link</button></div></div><div class="field"><label for="packSearch">DISCOVER ON GITHUB</label><input class="input" id="packSearch" placeholder="SCP:SL translation"><button class="button" id="searchPacks">Search repositories</button></div></section><section class="panel"><div class="label">INSTALLED</div><h2>Your packs</h2><div class="table-list">'+(state.packs.packs?.map(p=>'<div class="table-item"><span><strong>'+esc(p.name)+'</strong><small>'+esc((p.authors||[]).join(', '))+'</small></span><button class="button" data-activate="'+esc(p.id)+'">Activate</button><button class="button" data-main-pack-open="'+esc(p.id)+'">Open folder</button><button class="button" data-main-pack-restore="'+esc(p.id)+'">Restore backup</button><button class="button danger" data-pack-delete="'+esc(p.id)+'">Delete</button></div>').join('')||'<div class="empty">No custom packs installed.</div>')+'</div><button class="button" id="defaultPack">Use SCP:SL default</button><div id="packResults"></div></section></div></section>';
const wireWithPacks=wire;wire=()=>{wireWithPacks();if(page!=='packs')return;$('#installDirectPackLink')?.addEventListener('click',async()=>{const url=$('#directPackLink').value.trim();if(!url)return;const result=await call('install_translation_link',url);if(result?.ok){state.packs=result.packs;toast('Translation pack installed');render()}else toast(result?.error||'Could not install pack')});$('#searchPacks')?.addEventListener('click',async()=>{const result=await call('search_translation_packs',$('#packSearch').value.trim()||'SCP:SL translation'),items=result?.results||[];$('#packResults').innerHTML=items.map(item=>'<div class="table-item"><span><strong>'+esc(item.full_name||'Repository')+'</strong><small>'+esc(item.description||'No description')+'</small></span><button class="button" data-main-repo-install="'+esc(item.html_url||'')+'">Install</button></div>').join('')||'<div class="empty">No translation repositories found.</div>';document.querySelectorAll('[data-main-repo-install]').forEach(button=>button.onclick=async()=>{const installed=await call('install_translation_link',button.dataset.mainRepoInstall);if(installed?.ok){state.packs=installed.packs;render()}else toast(installed?.error||'Could not install pack')})});document.querySelectorAll('[data-main-pack-open]').forEach(button=>button.onclick=()=>call('open_translation_folder',button.dataset.mainPackOpen));document.querySelectorAll('[data-main-pack-restore]').forEach(button=>button.onclick=async()=>{const result=await call('restore_translation_backup',button.dataset.mainPackRestore);if(result?.packs){state.packs=result.packs;render()}else toast(result?.error||'No backup exists')})};

const presetColors={violet:'#b186ff',amber:'#e0a458',slate:'#71b7d8',light:'#6941c6','light-warm':'#8a5a24','light-slate':'#216b89'};
const oldThemeRender=render;render=()=>{oldThemeRender();if(page==='settings'){const swatches=document.querySelector('.swatches');['light','light-warm','light-slate'].forEach(name=>{if(swatches&&!swatches.querySelector('[data-theme="'+name+'"]')){const b=document.createElement('button');b.className='swatch';b.title=name;b.dataset.theme=name;b.style.background=presetColors[name];b.setAttribute('aria-label',name);swatches.appendChild(b)}})}};
document.addEventListener('click',async e=>{const b=e.target.closest('[data-theme]');if(!b)return;const name=b.dataset.theme;document.documentElement.classList.toggle('light-mode',name.startsWith('light'));document.documentElement.classList.toggle('light-warm',name==='light-warm');document.documentElement.classList.toggle('light-slate',name==='light-slate');if(presetColors[name])document.documentElement.style.setProperty('--accent',presetColors[name]);if(name.startsWith('light')){const r=await call('set_theme',name);if(r?.theme){state.theme=r.theme;render()}}});

// Settings are owned here, alongside their backend calls.  Do not depend on
// the compatibility script for storage, retry, or notification preferences.
const renderMainSettings=render;render=()=>{renderMainSettings();if(page!=='settings')return;const panel=document.querySelector('.settings .panel');if(!panel||$('#mainStorageTools'))return;const tools=document.createElement('section');tools.id='mainStorageTools';tools.className='settings-advanced';tools.innerHTML='<div class="label">LOCAL DATA</div><div class="actions"><button class="button" id="mainExportData">Export data</button><button class="button" id="mainOpenDataFolder">Open AppData folder</button><button class="button danger" id="mainResetData">Reset app data</button></div><div id="mainAdvancedSettings"><div class="label">COMPATIBILITY & NOTIFICATIONS</div><div class="setting-row"><div><strong>Navigation mode</strong><small>Automatic scales to the live game window; manual uses calibration.</small></div><select class="input" id="mainNavigationMode"><option value="automatic">Automatic scaling</option><option value="manual">Saved calibration</option></select></div><div class="setting-row"><div><strong>Connection timeout</strong><small>Seconds allowed for one attempt.</small></div><input class="input" id="mainAttemptTimeout" type="number" min="1"></div><div class="setting-row"><div><strong>Group looping</strong><small>Return to the first saved server after the last one.</small></div><label class="toggle"><input type="checkbox" id="mainGroupLoop"><span>Loop groups</span></label></div><div class="setting-row"><div><strong>Windows notifications</strong><small>Notify when a run completes or fails.</small></div><label class="toggle"><input type="checkbox" id="mainNotifications"><span>Notifications</span></label></div><div class="setting-row"><div><strong>Automatic updates</strong><small>Offer verified GitHub releases.</small></div><label class="toggle"><input type="checkbox" id="mainAutoUpdate"><span>Offer updates</span></label></div></div>';panel.appendChild(tools);$('#mainNavigationMode').value=state.settings.navigation_mode||'automatic';$('#mainAttemptTimeout').value=state.settings.attempt_timeout_s??20;$('#mainGroupLoop').checked=!!state.settings.group_loop;$('#mainNotifications').checked=state.settings.notifications_enabled!==false;$('#mainAutoUpdate').checked=!!state.settings.auto_update;[['mainNavigationMode','navigation_mode'],['mainAttemptTimeout','attempt_timeout_s'],['mainGroupLoop','group_loop'],['mainNotifications','notifications_enabled'],['mainAutoUpdate','auto_update']].forEach(([id,key])=>{$('#'+id).onchange=async e=>{const value=e.target.type==='checkbox'?e.target.checked:e.target.type==='number'?Number(e.target.value):e.target.value;const result=await call('save_setting',key,value);if(result?.settings)state.settings={...state.settings,...result.settings};else toast(result?.error||'Could not save setting')}});$('#mainExportData').onclick=async()=>{const result=await call('export_local_data');toast(result?.ok?'Local data exported to AppData':(result?.error||'Export failed'))};$('#mainOpenDataFolder').onclick=()=>call('open_data_folder');$('#mainResetData').onclick=async()=>{if(!await ask('Reset saved servers, groups, settings, and calibration? Translation packs are not removed.',{title:'Reset app data',confirmText:'Reset',danger:true}))return;const result=await call('reset_local_storage');if(result?.ok){Object.assign(state,result);selected=null;toast('App data reset');render()}}};

let mainGroupId=null,mainGroupIds=[];const renderMainServers=render;render=()=>{renderMainServers();if(page!=='servers')return;const host=document.querySelector('.layout > section:nth-child(2)');if(!host||$('#mainGroupEditor'))return;const group=state.groups.find(item=>item.id===(mainGroupId||state.groups[0]?.id));mainGroupId=group?.id||null;mainGroupIds=[...(group?.server_ids||mainGroupIds)];const box=document.createElement('section');box.id='mainGroupEditor';box.className='group-editor';const row=(server,index)=>'<div class="member-row"><span><strong>'+esc(server.name)+'</strong><small>'+esc(server.ip)+':'+server.port+'</small></span><button class="button" data-main-group-up="'+esc(server.id)+'" '+(index?'':'disabled')+'>Move up</button><button class="button" data-main-group-down="'+esc(server.id)+'" '+(index<mainGroupIds.length-1?'':'disabled')+'>Move down</button></div>';box.innerHTML='<div class="label">ORDERED GROUP EDITOR</div><h2>Retry order</h2><p>Only the visible order is used when this group starts.</p><select class="input" id="mainGroupSelect"><option value="">New group</option>'+state.groups.map(item=>'<option value="'+esc(item.id)+'" '+(item.id===mainGroupId?'selected':'')+'>'+esc(item.name)+'</option>').join('')+'</select><input class="input" id="mainGroupName" placeholder="Group name" value="'+esc(group?.name||'')+'"><div id="mainGroupMembers">'+mainGroupIds.map((id,index)=>state.servers.find(server=>server.id===id)).filter(Boolean).map(row).join('')+'</div><div class="actions"><button class="button" id="mainRememberServer">Remember current connection</button><button class="button primary" id="mainSaveGroup">Save group</button></div>';host.appendChild(box);$('#mainGroupSelect').onchange=e=>{mainGroupId=e.target.value||null;mainGroupIds=[...(state.groups.find(item=>item.id===mainGroupId)?.server_ids||[])];render()};document.querySelectorAll('[data-main-group-up]').forEach(button=>button.onclick=()=>{const i=mainGroupIds.indexOf(button.dataset.mainGroupUp);if(i>0)[mainGroupIds[i-1],mainGroupIds[i]]=[mainGroupIds[i],mainGroupIds[i-1]];render()});document.querySelectorAll('[data-main-group-down]').forEach(button=>button.onclick=()=>{const i=mainGroupIds.indexOf(button.dataset.mainGroupDown);if(i>=0&&i<mainGroupIds.length-1)[mainGroupIds[i],mainGroupIds[i+1]]=[mainGroupIds[i+1],mainGroupIds[i]];render()});$('#mainRememberServer').onclick=async()=>{const result=await call('start_remember');toast(result?.ok?'Watching Player.log for your next connection.':(result?.error||'Could not start connection detection'))};$('#mainSaveGroup').onclick=async()=>{const name=$('#mainGroupName').value.trim(),result=await call('save_group',name,mainGroupIds,mainGroupId);if(result?.ok){state.groups=mainGroupId?state.groups.map(item=>item.id===result.group.id?result.group:item):[...state.groups,result.group];mainGroupId=result.group.id;toast('Server group saved');render()}else toast(result?.error||'Add a group name and servers first')}};
document.addEventListener('click',e=>{const down=e.target.closest?.('[data-main-group-down]'),up=e.target.closest?.('[data-main-group-up]');if(!down&&!up)return;e.preventDefault();e.stopImmediatePropagation();const id=(down||up).dataset.mainGroupDown||(down||up).dataset.mainGroupUp,index=mainGroupIds.indexOf(id),next=down?index+1:index-1;if(next<0||next>=mainGroupIds.length)return;[mainGroupIds[index],mainGroupIds[next]]=[mainGroupIds[next],mainGroupIds[index]];const row=(down||up).closest('.member-row'),sibling=down?row.nextElementSibling:row.previousElementSibling;if(down)sibling?.after(row);else sibling?.before(row)},true);
document.addEventListener('change',e=>{if(e.target.id!=='mainGroupSelect'||e.target.value!=='')return;e.stopImmediatePropagation();mainGroupId='__new__';mainGroupIds=state.servers.map(item=>item.id);render()},true);
function mainServerForm(title,server){const overlay=document.createElement('div');overlay.className='modal-backdrop';overlay.innerHTML='<section class="confirm-modal form-modal" role="dialog" aria-modal="true"><div class="modal-kicker">SAVED SERVER</div><h2>'+esc(title)+'</h2><form><label class="field"><span>DISPLAY NAME</span><input class="input" id="mainServerFormName" required></label><label class="field"><span>IP OR HOSTNAME:PORT</span><input class="input" id="mainServerFormEndpoint" required></label><div class="modal-actions"><button class="button" type="button" id="mainServerFormCancel">Cancel</button><button class="button primary" type="submit">Save</button></div></form></section>';$('#mainServerFormName',overlay).value=server?.name||'';$('#mainServerFormEndpoint',overlay).value=server?server.ip+':'+server.port:'';$('#mainServerFormCancel',overlay).onclick=()=>overlay.remove();$('form',overlay).onsubmit=async e=>{e.preventDefault();const name=$('#mainServerFormName',overlay).value.trim(),endpoint=$('#mainServerFormEndpoint',overlay).value.trim(),split=endpoint.lastIndexOf(':');if(!name||split<=0)return toast('Enter a display name and endpoint such as 127.0.0.1:7777');const result=server?await call('rename_server',server.id,name):await call('save_server',name,endpoint.slice(0,split),Number(endpoint.slice(split+1)));if(!result?.ok)return toast(result?.error||'Could not save server');state.servers=server?state.servers.map(item=>item.id===server.id?result.server:item):[...state.servers,result.server];selected=result.server.id;overlay.remove();render()};document.body.appendChild(overlay);$('#mainServerFormName',overlay).focus()}
function mainDetectedServerForm(data){const overlay=document.createElement('div'),endpoint=String(data.ip||'')+':'+String(data.port||'');overlay.className='modal-backdrop';overlay.innerHTML='<section class="confirm-modal form-modal" role="dialog" aria-modal="true"><div class="modal-kicker">CONNECTION DETECTED</div><h2>Save detected server</h2><form><label class="field"><span>DISPLAY NAME</span><input class="input" id="mainServerFormName" required></label><label class="field"><span>DETECTED ENDPOINT</span><input class="input" id="mainServerFormEndpoint" required></label><div class="modal-actions"><button class="button" type="button" id="mainServerFormCancel">Cancel</button><button class="button primary" type="submit">Save server</button></div></form></section>';$('#mainServerFormName',overlay).value=data.name||endpoint;$('#mainServerFormEndpoint',overlay).value=endpoint;$('#mainServerFormCancel',overlay).onclick=()=>overlay.remove();$('form',overlay).onsubmit=async e=>{e.preventDefault();const name=$('#mainServerFormName',overlay).value.trim(),value=$('#mainServerFormEndpoint',overlay).value.trim(),split=value.lastIndexOf(':');if(!name||split<=0)return toast('Enter a valid server name and endpoint');const result=await call('remember_server',name,value.slice(0,split),Number(value.slice(split+1)));if(!result?.ok)return toast(result?.error||'Could not save detected server');state.servers=[...state.servers.filter(item=>item.id!==result.server.id),result.server];selected=result.server.id;overlay.remove();page='servers';render();toast('Detected server saved')};document.body.appendChild(overlay);$('#mainServerFormName',overlay).focus()}
const mainEventHandler=window.__appEvent;window.__appEvent=event=>{mainEventHandler?.(event);if(event?.event==='server_detected')mainDetectedServerForm(event.data||{})};
document.addEventListener('click',e=>{const button=e.target.closest?.('#addServer,[data-rename]');if(!button)return;e.preventDefault();e.stopImmediatePropagation();const server=button.dataset.rename?state.servers.find(item=>item.id===button.dataset.rename):null;mainServerForm(server?'Rename saved server':'Add saved server',server)},true);
const renderStoredTheme=render;render=()=>{renderStoredTheme();const preset=state.theme?.preset||'violet',colors={violet:'#b186ff',amber:'#e0a458',slate:'#71b7d8',light:'#6941c6','light-warm':'#8a5a24','light-slate':'#216b89'};document.documentElement.classList.toggle('light-mode',preset.startsWith('light'));document.documentElement.classList.toggle('light-warm',preset==='light-warm');document.documentElement.classList.toggle('light-slate',preset==='light-slate');document.documentElement.style.setProperty('--accent',state.settings?.accent==='custom'?state.settings.custom_accent:(colors[preset]||colors.violet));let style=$('#storedCustomTheme');if(style)style.remove();if(state.theme?.custom?.compiled){style=document.createElement('style');style.id='storedCustomTheme';style.textContent=state.theme.custom.compiled;document.head.appendChild(style)}};
const renderRememberAction=render;render=()=>{renderRememberAction();if(page!=='servers')return;$('#mainRememberServer')?.remove();const actions=document.querySelector('.layout > section:first-child .actions');if(!actions||$('#rememberServerFromLog'))return;const block=document.createElement('div');block.className='remember-server-block';block.innerHTML='<button class="button remember-server-button" id="rememberServerFromLog" title="Watch SCP:SL Player.log for your next connection and query the server name automatically."><strong>Remember server from Player.log</strong><span>Press this, then join normally in SCP:SL. The app detects the endpoint and queries its name.</span></button><small id="rememberServerStatus" class="endpoint" role="status">Reads only the next connection entry from Player.log.</small>';actions.appendChild(block);$('#rememberServerFromLog').onclick=async()=>{const button=$('#rememberServerFromLog'),status=$('#rememberServerStatus');button.disabled=true;status.textContent='Watching Player.log. Join normally in SCP:SL; the detected name and endpoint will appear here.';const result=await call('start_remember');if(!result?.ok){button.disabled=false;status.textContent=result?.error||'Could not start connection detection';toast(status.textContent)}}};
document.addEventListener('click',e=>{if(e.target.id==='resetAppearance')document.documentElement.classList.remove('light-mode')});
document.addEventListener('click',async e=>{const target=e.target.closest?.('[data-delete],[data-pack-delete],[data-group-delete]');if(!target)return;e.preventDefault();e.stopImmediatePropagation();if(target.dataset.delete){if(await ask('Delete this saved server?',{title:'Delete saved server',confirmText:'Delete',danger:true})){await call('delete_server',target.dataset.delete);state.servers=state.servers.filter(x=>x.id!==target.dataset.delete);render()}}else if(target.dataset.packDelete){if(await ask('Delete this translation pack?',{title:'Delete translation pack',confirmText:'Delete',danger:true})){const r=await call('delete_translation_pack',target.dataset.packDelete);if(r?.packs)state.packs=r.packs;render()}}else if(target.dataset.groupDelete){if(await ask('Delete this server group?',{title:'Delete server group',confirmText:'Delete',danger:true})){const r=await call('delete_group',target.dataset.groupDelete);if(r?.deleted){state.groups=state.groups.filter(x=>x.id!==target.dataset.groupDelete);render()}}}},true);
let availableUpdate=null;const oldUpdaterRender=render;render=()=>{oldUpdaterRender();if(page==='settings'){const panel=document.querySelector('.settings .panel');if(panel&&!document.querySelector('#updateTools')){const box=document.createElement('div');box.className='setting-row';box.id='updateTools';box.innerHTML='<div><strong>Software updates</strong><small>Check GitHub for a published release. Updates preserve your local settings and server data.</small></div><div class="update-actions"><button class="button" id="checkUpdates">Check for updates</button><button class="button primary" id="installUpdate" hidden>Install update</button><small id="updateStatus" role="status"></small></div>';panel.appendChild(box);$('#checkUpdates').onclick=async()=>{const r=await call('get_update_status');availableUpdate=r?.update||null;$('#updateStatus').textContent=availableUpdate?'v'+availableUpdate.version+' is available.':'You are up to date.';$('#installUpdate').hidden=!availableUpdate};$('#installUpdate').onclick=async()=>{if(!availableUpdate)return;$('#updateStatus').textContent='Downloading and verifying…';const r=await call('install_update',availableUpdate);$('#updateStatus').textContent=r?.ok?'Update verified. Restarting…':(r?.error||'Update failed.')}}}};document.addEventListener('DOMContentLoaded',()=>{const v=state.version||'0.3.34';if($('#versionLabel'))$('#versionLabel').textContent='BUILD '+v+' / WEBVIEW2'});
